243.docs:
Errors generated when the mo files parser can't parse some content.

# Examples

## Unsupported MO revision number

```rust
use rspolib::{mofile, errors::IOError, MAGIC};
use rspolib_testing::create_binary_content;

let version = 234;
let data = vec![MAGIC, version];
let content = create_binary_content(&data, true);

assert_eq!(
  mofile(content),
  Err(IOError::UnsupportedMORevisionNumber { version }),
);
```

## Incorrect magic number

```
use rspolib::{mofile, errors::IOError};
use rspolib_testing::create_binary_content;

let magic_number = 800;
let data = vec![magic_number];
let content = create_binary_content(&data, true);

assert_eq!(
    mofile(content),
    Err(IOError::IncorrectMagicNumber {
        magic_number_le: magic_number,
        magic_number_be: 537067520
    })
);
```

12.docs:
A struct to compare two entries.

```rust
use std::cmp::Ordering;
use rspolib::{POEntry, EntryCmpByOptions};

let mut entry1 = POEntry::from("msgid 1");
let entry2 = POEntry::from("msgid 2");

let compare_by_all_fields = EntryCmpByOptions::new();
let compare_by_msgid_only = EntryCmpByOptions::new()
    .by_all(false)
    .by_msgid(true);

assert_eq!(entry1.cmp_by(&entry2, &compare_by_msgid_only), Ordering::Less);
assert_eq!(entry2.cmp_by(&entry1, &compare_by_msgid_only), Ordering::Greater);

entry1.msgid = "msgid 2".to_string();
assert_eq!(entry1.cmp_by(&entry2, &compare_by_msgid_only), Ordering::Equal);

entry1.msgstr = Some("msgstr 1".to_string());
assert_eq!(entry1.cmp_by(&entry2, &compare_by_msgid_only), Ordering::Equal);
assert_eq!(entry1.cmp_by(&entry2, &compare_by_all_fields), Ordering::Greater);
```

439.docs:
PO files factory function.

It takes an argument that could be either:

* A string as path to an existent file.
* The content of a PO file as string.
* The content of a PO file as bytes.
* A [FileOptions] struct.

# Examples

## Open from path

```rust
use rspolib::pofile;

let file = pofile("tests-data/obsoletes.po").unwrap();
```

## Open from content

```rust
use rspolib::pofile;

let content = r#"#
msgid ""
msgstr ""

msgid "A message"
msgstr "Un mensaje"
"#;

let file = pofile(content).unwrap();
```

## Open from bytes

```rust
use std::fs;
use rspolib::pofile;

let bytes_content = fs::read("tests-data/all.po").unwrap();
let file = pofile(bytes_content).unwrap();
```

## Tuples into [FileOptions]

```rust
use rspolib::pofile;

// Wrap width
let file = pofile(("tests-data/all.po", 75)).unwrap();
```

## Explicitly from [FileOptions]

```rust
use std::fs;
use rspolib::{pofile, FileOptions as POFileOptions};

let file = pofile(POFileOptions::default()).unwrap();

// Path or content
let opts = POFileOptions::from("tests-data/obsoletes.po");
let file = pofile(opts).unwrap();

// Wrap width
let opts = POFileOptions::from(("tests-data/all.po", 75));
let file = pofile(opts).unwrap();
```

360.docs:
Errors generated by the parsers

# Complete example

## Read a PO file (SyntaxError)

```rust
use rspolib::{pofile, POFile, errors::SyntaxError};

let path = "tests-data/unescaped-double-quote-msgid.po";

let file: Option<POFile> = match pofile(path) {
    Ok(file) => Some(file),
    Err(e) => match e {
        ref SyntaxError => {
            assert!(e.to_string().ends_with("unescaped double quote found"));
            None
        },
    },
};
```

## Read a MO file (IOError)

```rust
use rspolib::{mofile, MOFile, errors::IOError, MAGIC};
use rspolib_testing::create_binary_content;

let version = 0;
let data = vec![MAGIC, version];
let content = create_binary_content(&data, true);

let file: Option<MOFile> = match mofile(content) {
    Ok(file) => Some(file),
    Err(e) => match e {
        ref IOError => {
            assert!(e.to_string().ends_with("malformed or corrupted data found when parsing number of strings"));
            None
        },
    },
};
```
